policy:
{
  // Two shortcuts Tailground expands before compiling:
  //   user:*@corp.example  — everyone whose email ends in that domain
  //   autogroup:admin      — everyone whose snapshot role is owner or admin
  // Add two grants:
  //   1. anyone at corp.example reaches tag:wiki on 443
  //   2. autogroup:admin reaches tag:infra on 22
  "tagOwners": {
    "tag:wiki": ["autogroup:admin"],
    "tag:infra": ["autogroup:admin"],
  },
  "grants": [
    // TODO
  ],
  "tests": [
    { "src": "bob@corp.example",     "accept": ["tag:wiki:443"], "deny": ["tag:infra:22"] },
    { "src": "carol@contractor.dev", "deny":   ["tag:wiki:443", "tag:infra:22"] },
    { "src": "alice@corp.example",   "accept": ["tag:wiki:443", "tag:infra:22"] },
  ],
}
